// frontend/src/components/Navbar.jsx
import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { User, Bell, ChevronDown } from 'lucide-react'; 

const Navbar = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [showDropdown, setShowDropdown] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <nav className="bg-white text-gray-800 border-b border-gray-100 sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 py-3 xl:px-8 flex justify-between items-center text-sm font-medium">
        {/* Logo */}
        <Link to="/" className="flex items-center gap-1 text-2xl font-bold text-[#0096ff]">
          <svg width="40" height="40" viewBox="0 0 32 32" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M7 16H25V18H7V16ZM4 20H28C29.1046 20 30 20.8954 30 22V24H2V22C2 20.8954 2.89543 20 4 20ZM7 12L9 8H23L25 12H7Z" fill="currentColor"/>
          </svg>
          <span className="tracking-tighter">vucar</span>
        </Link>

        {/* Center Links */}
        <div className="hidden lg:flex items-center space-x-7 text-[#3f4b53]">
          <Link to="#" className="hover:text-[#0096ff]">Mua xe</Link>
          <div className="flex items-center gap-1 cursor-pointer hover:text-[#0096ff]">
            Bán xe <ChevronDown size={14} className="text-gray-400" />
          </div>
          <div className="flex items-center gap-1 cursor-pointer hover:text-[#0096ff]">
            Khám phá <ChevronDown size={14} className="text-gray-400" />
          </div>
          <div className="flex items-center gap-1 cursor-pointer hover:text-[#0096ff]">
            Về Vucar <ChevronDown size={14} className="text-gray-400" />
          </div>
          <Link to="#" className="text-[#0096ff] flex items-center gap-1">
            Lên xế điện <span className="bg-[#0096ff] text-white text-[10px] px-2 py-0.5 rounded-full font-bold">Mới</span>
          </Link>
        </div>

        {/* Right Links */}
        <div className="flex items-center gap-5">
          {user ? (
            <div className="relative">
              <button 
                onClick={() => setShowDropdown(!showDropdown)}
                className="w-[42px] h-[42px] rounded-full bg-[#0096ff] text-white flex items-center justify-center hover:bg-blue-600 transition shadow-sm"
              >
                <User size={22} strokeWidth={2} />
              </button>

              {showDropdown && (
                <>
                  <div 
                    className="fixed inset-0 z-40" 
                    onClick={() => setShowDropdown(false)}
                  ></div>
                  <div className="absolute top-12 right-0 mt-3 bg-white rounded-2xl shadow-[0_4px_25px_rgba(0,0,0,0.08)] border border-gray-100 p-3 flex items-center gap-4 z-50 transform origin-top-right transition-all">
                    <span className="text-[15px] font-semibold text-[#003b5c] whitespace-nowrap pl-2">
                      Xin chào, {user.name || user.phone || 'Khách hàng'}
                    </span>
                    <button 
                      onClick={handleLogout} 
                      className="text-sm border border-gray-200 text-[#003b5c] font-semibold px-4 py-2 rounded-xl hover:bg-gray-50 flex items-center transition"
                    >
                      Đăng xuất
                    </button>
                    <button className="relative w-10 h-10 rounded-full border border-gray-200 flex items-center justify-center hover:bg-gray-50 text-gray-600 transition shrink-0">
                      <Bell size={18} strokeWidth={2} className="text-[#3f4b53]"/>
                      <span className="absolute top-2.5 right-2.5 w-2 h-2 bg-[#ff4a4a] rounded-full"></span>
                    </button>
                  </div>
                </>
              )}
            </div>
          ) : (
            <div className="flex items-center gap-4">
              <Link to="/login" className="border border-gray-200 text-gray-600 px-4 py-2 rounded-lg hover:bg-gray-50 flex items-center gap-2">
                <User size={16} /> Tài khoản
              </Link>
              <button className="relative p-2 rounded-full hover:bg-gray-50 border border-gray-200 text-gray-600">
                <Bell size={18} />
                <span className="absolute top-1.5 right-1.5 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white"></span>
              </button>
            </div>
          )}
          
          <div className="hidden sm:flex flex-col text-right border-l pl-5 border-gray-200">
            <span className="text-[11px] text-gray-500 leading-none mb-1">Hotline:</span>
            <span className="text-[#0096ff] font-bold text-base leading-none">1800 646 896</span>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
